[SubscribesTo(formStr(RetailPricingSimulator), delegateStr(RetailPricingSimulator, setInfoFromCustomerWithoutChannelInfo))]
public static void RetailPricingSimulator_setInfoFromCustomerWithoutChannelInfo(RetailPricingSimulatorSalesTransaction _retailPricingSimulatorSalesTransaction, CustTable _selectedCustomer)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (_retailPricingSimulatorSalesTransaction.ChannelCurrency == '' && _selectedCustomer.RecId)
        {
            _retailPricingSimulatorSalesTransaction.ChannelCurrency = _selectedCustomer.Currency;
        }
    }
}
